td.style:
padding: 8px;
                                                               vertical-align: top;
                                                               width: 30%;
                                                               border: none;
                                                               white-space: normal;
                                                               overflow-wrap: break-word;
                                                               word-break: break-word;
                                                               line-height: 1.6;

form.script:
function togglePwd(el) {
var input = el.closest('div').querySelector('input');
var icon = el.querySelector('i');
if (!input) return;
if (input.type === 'password') {
input.type = 'text';
icon.className = 'fa fa-eye-slash';
} else {
input.type = 'password';
icon.className = 'fa fa-eye';
}
}
